//! `spider check [--strict] [--modules]`: the app's conventions
//! (src/conventions.zig in Spider) — routes in routes.zig with declared
//! access, ui-* classes, icons from active sets, features registered. Exit 1
//! on errors (and on warnings with --strict). Apps generated by spider new
//! run the same checks in `zig build test` (spider.testing.expectConventions()).
//! With --modules it also runs the app with SPIDER_CHECK set: every mounted
//! module's checks, as listen() runs them before it starts (modules_cmd.zig).

const std = @import("std");
const conventions = @import("spider_testing").conventions;
const fs_utils = @import("fs_utils.zig");
const modules_cmd = @import("modules_cmd.zig");

pub fn run(io: std.Io, allocator: std.mem.Allocator, environ_map: *std.process.Environ.Map, args: []const []const u8) !u8 {
    var strict = false;
    var modules = false;
    for (args) |a| {
        if (std.mem.eql(u8, a, "--strict")) {
            strict = true;
        } else if (std.mem.eql(u8, a, "--modules")) {
            modules = true;
        } else {
            std.debug.print("error: unknown option '{s}' for `spider check` (see `spider check --help`)\n", .{a});
            return 2;
        }
    }
    const root = fs_utils.findProjectRoot(io) catch {
        std.debug.print("error: not inside a Spider app (no build.zig.zon here or above)\n", .{});
        return 2;
    };
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    var report: conventions.Report = .{ .arena = arena.allocator() };
    try conventions.check(io, arena.allocator(), root, &report);

    var buf: [4096]u8 = undefined;
    var w = std.Io.File.stdout().writer(io, &buf);
    if (report.issues.items.len == 0) {
        try w.interface.writeAll("ok: the app follows Spider's conventions\n");
    } else {
        try report.write(&w.interface);
    }
    try w.interface.flush();
    var code: u8 = 0;
    if (report.count(.err) > 0) code = 1;
    if (strict and report.count(.warn) > 0) code = 1;
    if (modules) {
        // The app checks its modules itself (database, environment).
        if (try modules_cmd.runApp(io, environ_map, "SPIDER_CHECK") != 0) code = 1;
    }
    return code;
}
